import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import Error503 from './Error503';

describe('503 Page', () => {
  const mockFunction = jest.fn();
  it('should render the 503 page without crashing', () => {
    render(
      <Error503
        headerText="Hm... Service unavailable!"
        subheaderText="Our servers are temporarily too busy. You can try again in a few minutes, and it should be normalized."
        infoText="If the issue persists, you can report the problem."
        buttonText="Try again"
        buttonClickHandler={mockFunction}
      />
    );
    expect(screen.getByText('Hm... Service unavailable!')).toBeInTheDocument();
  });

  it('should call button click function when button is clicked', () => {
    render(
      <Error503
        headerText="Mmm… Looks like this page is gone"
        subHeaderText="It looks like this page wasn’t found or doesn’t exist."
        buttonText="Home"
        buttonClickHandler={mockFunction}
      />
    );
    const button = screen.getByTestId('error503-button');
    fireEvent.click(button);
    expect(mockFunction).toHaveBeenCalled();
  });
});
